function Tracking({me,notify}:any){const q=new URLSearchParams(location.search),id=q.get('track'),token=q.get('token');const [order,setOrder]=useState<any>(null),[error,setError]=useState(''),[confirm,setConfirm]=useState(false),[busy,setBusy]=useState(false);async function load(){try{setOrder(await request('data?track='+encodeURIComponent(id||'')+'&token='+encodeURIComponent(token||'')));setError('')}catch(e:any){setError(e.message)}}useEffect(()=>{load();const t=setInterval(load,10000);return()=>clearInterval(t)},[]);const sequence=['new','working','ready','done'],index=order?sequence.indexOf(order.status):-1,canCancel=order&&!['done','cancelled'].includes(order.status)&&order.due-Date.now()>=86400000;return <><div className="public-page tracking-page"><header><Brand/><span><LockKeyhole size={14}/> {tx("Ваша персональная ссылка")}</span></header><main><p className="eyebrow">{tx("СТАТУС ВАШЕЙ ЗАЯВКИ")}</p><h1>{order?.status==='cancelled'?tx("Заявка отменена"):order?.experience?.isService?tx("Ваша запись — под контролем"):tx("Ваш заказ — под контролем")}</h1><p className="subtle">{tx("Сохраните эту ссылку. Она открывает детали заказа, поэтому делитесь ею только с теми, кому доверяете.")}</p>{error?<Notice kind="warning">{error}</Notice>:!order?<div className="loading"><span/> {tx("Проверяем статус…")}</div>:<><section className="card tracking-card"><div className="tracking-title"><div><small>{order.businessName} · #{order.id.slice(0,8)}</small><h2>{order.data.product}</h2></div><Status status={order.status} experience={order.experience}/></div><div className="tracking-timeline">{sequence.map((s,i)=><div key={s} className={i<=index?'complete':''}><span>{i<=index?<Check size={17}/>:i+1}</span><b>{order.experience?.statuses?.[s]||LABELS[s]}</b></div>)}</div><div className="tracking-summary"><div><CalendarDays size={18}/><span>{order.experience?.dueLabel||tx("Дата и время")}<b>{date(order.due)}</b></span></div><div><Package size={18}/><span>{tx("Количество")}<b>{order.data.qty} {order.experience?.unit||tx("ед.")}</b></span></div><div><ShoppingBag size={18}/><span>{tx("Сумма заказа")}<b>{money(order.data.total,order.data.currency)}</b></span></div></div>{order.data.note&&<div className="order-note"><span>{tx("Ваши пожелания")}</span><p>{order.data.note}</p></div>}{order.pickupInstructions&&<Notice><Home size={16}/>{order.pickupInstructions}</Notice>}<div className="tracking-actions"><Button secondary onClick={async()=>{try{await navigator.clipboard.writeText(location.href);notify(tx("Ссылка отслеживания скопирована"))}catch{notify(tx("Скопируйте адрес из строки браузера."))}}}><Copy size={15}/> {tx("Скопировать ссылку")}</Button><Button secondary disabled={!canCancel} onClick={()=>setConfirm(true)}>{tx("Отменить заказ")}</Button></div><p className="muted-small">{order.status==='cancelled'?tx("Отмена зарегистрирована."):canCancel?tx("Вы можете отменить заказ до ")+date(order.due-86400000)+'.':tx("Отмена недоступна: до получения осталось меньше 24 часов либо заказ уже завершён.")}</p></section><SellerNotice/><a className="text-link" href={'/?b='+order.business}>{tx("Вернуться к бизнесу")} <ArrowRight size={14}/></a></>}{confirm&&<Modal title={tx("Отменить заказ?")} subtitle={tx("Продавец увидит отмену в своём кабинете")} onClose={()=>setConfirm(false)}><div className="button-row"><Button secondary onClick={()=>setConfirm(false)}>{tx("Оставить заказ")}</Button><Button disabled={busy} onClick={async()=>{setBusy(true);try{await request('data',{action:'cancel',id,token});await load();setConfirm(false);notify(tx("Заказ отменён"))}catch(e:any){notify(e.message)}finally{setBusy(false)}}}>{tx("Подтвердить отмену")}</Button></div></Modal>}</main></div></>}
function PrivacyPage({me}:any){return <><div className="public-page privacy-page"><header><Brand/><a className="text-link" href={storefrontHref(location.search)}>{tx("Вернуться назад")} <ArrowRight size={14}/></a></header><main><p className="eyebrow">{tx("ПОНЯТНЫЕ УСЛОВИЯ. БОЛЬШЕ ДОВЕРИЯ.")}</p><h1>{tx("Кто отвечает за товар")}<br/>{tx("и что происходит с данными")}</h1><p className="subtle">{tx("Дело дома — инструмент для оформления и отслеживания заказов домашнего микробизнеса.")}</p><section className="card policy-card"><span className="feature-icon"><Home size={22}/></span><h2>{tx("За качество отвечает продавец")}</h2><p>{tx("За качество товаров и услуг, безопасность и соответствие описанию отвечает продавец — владелец бизнеса, а не платформа «Дело дома».")} {tx("Именно продавец готовит или создаёт товар, указывает его состав, свойства и условия получения.")}</p><blockquote>“Business is responsible for the quality of the products, not the website.”</blockquote><p>{tx("По вопросам состава, аллергенов, качества и исполнения заказа обращайтесь к продавцу. Роль платформы — помочь с оформлением и статусом. Эта оговорка не отменяет собственные обязанности платформы по обработке данных.")}</p></section><section className="card policy-card"><span className="feature-icon"><LockKeyhole size={22}/></span><h2>{tx("Данные для заказа, а не для любопытства")}</h2><p>{tx("Имя, контакт, товар, пожелания и время получения нужны продавцу для выполнения заказа. Платформа хранит эти сведения на сервере. Новые контакты заказов и содержимое базы знаний шифруются; ключ не отправляется в браузер.")}</p><div className="role-policy-grid"><div><b>{tx("Владелец")}</b><p>{tx("Заказы, контакты своих клиентов, каталог, склад и файлы своего бизнеса.")}</p></div><div><b>{tx("Клиент")}</b><p>{tx("Публичный каталог и свой заказ по персональной ссылке.")}</p></div><div><b>{tx("Менеджер")}</b><p>{tx("Сотрудник площадки: агрегированная статистика всех бизнесов, маркетинг платформы и задачи команды. Без доступа к частным заказам, складам и файлам.")}</p></div><div><b>{tx("Администратор")}</b><p>{tx("Состояние бизнесов и журнал действий, без интерфейса чтения частных заказов и файлов.")}</p></div></div><p>{tx("После завершения заказа владелец может удалить контактные данные отдельно от сумм и товаров. В кабинете есть очистка контактов завершённых и отменённых заказов старше 90 дней. Для регулярного удаления оператор может запускать серверную команду purge_contacts по расписанию. В локальной демонстрации расписание не включено.")}</p></section><section className="card policy-card"><span className="feature-icon"><Sparkles size={22}/></span><h2>{tx("Помощник и загружаемые файлы")}</h2><p>{tx("Владелец загружает только сведения, на использование которых у него есть право. Сначала он проверяет импорт и активирует нужные столбцы. Содержимое файлов не публикуется клиентам как файл: помощник находит подходящие фрагменты для ответа.")}</p><p>{tx("Если владелец включит внешний ИИ и клиент разрешит обработку сообщений, каталог, описание бизнеса, соответствующие фрагменты знаний и сообщения будут передаваться настроенному провайдеру:")} {me.aiProviderName}{tx(". Для OpenAI используется")} <code>store: false</code>{tx(". Для Google Gemini действуют условия Google; на бесплатном тарифе переданные материалы могут использоваться для улучшения продуктов. Нельзя загружать секреты и лишние персональные данные. Имя и контакт клиента заполняются отдельно от диалога. Не включайте в сообщения секреты и лишние персональные данные.")}</p><p>{tx("По умолчанию используется локальный сценарий без запросов к OpenAI. Текущий провайдер:")} {me.aiMode==='local'?tx("локальный сценарий"):me.aiProviderName}{tx(". Внешняя модель требует отдельного согласия владельца и клиента на передачу данных этому провайдеру.")}</p></section><section className="card policy-card"><span className="feature-icon"><Clock size={22}/></span><h2>{tx("Отмена и статистика")}</h2><p>{tx("Клиент может отменить заказ не позднее чем за 24 часа до времени получения. После этого кнопка отмены недоступна, и срок дополнительно проверяется сервером.")}</p><p>{tx("Имя и контакты не входят в отчёты менеджера. Отдельный учёт посещения включается только по желанию посетителя. Регистрация заказа учитывается для работы бизнеса независимо от разрешения на статистику посещений. Техническая защита от частых запросов использует хеш сетевого адреса.")}</p><p>{tx("Маркетинговое согласие необязательно и по умолчанию выключено. Платформа не отправляет рекламу автоматически.")}</p></section><ExtraTerms/><p className="muted-small">{tx("Перед рабочим запуском владелец платформы должен указать свои реквизиты и канал обращений по данным и проверить условия с учётом страны работы. Эта страница описывает реализованный процесс, а не заменяет полноценные документы оператора.")}</p></main></div></>}
function AuthPage({me,notify}:any){const q=new URLSearchParams(location.search),invite=q.get('invite');const [signup,setSignup]=useState(!!invite||q.get('auth')==='signup'),[busy,setBusy]=useState(false);return <><div className="public-page auth-page"><header><Brand/><span><Home size={15}/> {tx("Для небольшого дела из дома")}</span></header><main><div className="auth-art"><BusinessArt hero/><span className="handwritten">{tx("пусть ваше дело")}<br/>{tx("расцветает")}</span><h2>{tx("Вы делаете любимое.")}<br/>{tx("Мы помогаем с остальным.")}</h2><p>{tx("Заказы, знания о бизнесе и клиенты — всё в одном уютном рабочем пространстве.")}</p></div><section className="card auth-card"><p className="eyebrow">{invite?tx("ПРИГЛАШЕНИЕ В КОМАНДУ ПЛОЩАДКИ"):tx("ДОБРО ПОЖАЛОВАТЬ В ДЕЛО ДОМА")}</p><h1>{signup?tx("Давайте начнём"):tx("С возвращением")}</h1><p className="subtle">{invite?tx("Зарегистрируйтесь с email, на который вас пригласили."):signup?tx("Создайте кабинет для вашего домашнего бизнеса."):tx("Войдите в свой кабинет владельца или менеджера.")}</p><form className="stack-form" onSubmit={async e=>{e.preventDefault();setBusy(true);const fd=new FormData(e.currentTarget);try{await request('auth',{action:signup?'signup':'login',email:fd.get('email'),password:fd.get('password'),name:fd.get('name'),termsAccepted:fd.get('terms')==='on',invite});location.href='/'}catch(e:any){notify(e.message)}finally{setBusy(false)}}}>{signup&&<label>{tx("Как к вам обращаться")}<input name="name" required maxLength={100} autoComplete="given-name"/></label>}<label>Email<input name="email" type="email" autoComplete="email" required maxLength={254}/></label><label>{tx("Пароль")}<input name="password" type="password" autoComplete={signup?'new-password':'current-password'} minLength={8} maxLength={128} required/></label><small className="muted-small">{tx("От 8 до 128 символов. Пароль хранится в виде защищённого хеша.")}</small><label className="check-label"><input type="checkbox" required name="terms"/><span>{tx("Я ознакомился с")} <a href={privacyHref(location.search)} target="_blank" rel="noreferrer">{tx("условиями, безопасностью и хранением данных")}</a>{tx(". За качество и безопасность своей продукции отвечает бизнес.")}</span></label><Button type="submit" disabled={busy}>{busy?tx("Подождите…"):signup?tx("Создать аккаунт"):tx("Войти")}<ArrowRight size={16}/></Button></form><button className="text-link auth-toggle" onClick={()=>setSignup(!signup)}>{signup?tx("Уже есть аккаунт? Войти"):tx("Нет аккаунта? Зарегистрироваться")}</button><a className="small-link" href={privacyHref(location.search)} target="_blank" rel="noreferrer">{tx("Данные и ответственность")} <ArrowUpRight size={12}/></a></section></main></div></>}
export default function App(){useLanguage();const [me,setMe]=useState<any>(null),[error,setError]=useState(''),[toast,setToast]=useState('');const q=new URLSearchParams(location.search);function notify(text:string){setToast(text);setTimeout(()=>setToast(''),5500)}useEffect(()=>{(async()=>{try{const v=await request('me');setMe(v)}catch(e:any){setError(e.message)}})()},[]);if(error)return <div className="public-page"><Brand/><Empty title={tx("Не удалось подключиться")} text={error}><Button onClick={()=>location.reload()}>{tx("Повторить")}</Button></Empty></div>;if(!me)return <div className="boot-screen"><Brand/><span className="boot-spinner"/><p>{tx("Готовим ваше уютное рабочее пространство…")}</p></div>;return <>{q.has('privacy')?<PrivacyPage me={me}/>:q.has('track')?<Tracking me={me} notify={notify}/>:q.has('b')?<ClientApp me={me} notify={notify}/>:q.has('auth')||!me.user?<AuthPage me={me} notify={notify}/>:me.user.role==='admin'?<AdminApp me={me} notify={notify}/>:me.user.role==='manager'?<ManagerApp me={me} notify={notify}/>:<BusinessApp me={me} notify={notify}/>}<div className="global-terms"><span>{tx("За качество товаров и услуг, безопасность и соответствие описанию отвечает продавец — владелец бизнеса, а не платформа «Дело дома».")}</span><a href={privacyHref(location.search)}>{tx("Условия, безопасность и данные")}</a></div><SiteHelp request={request} inventoryEnabled={me.features?.inventory===true}/><div className="toast-region" aria-live="polite">{toast&&<div className="toast"><span><CheckCircle2 size={17}/></span>{toast}<button aria-label={tx("Закрыть сообщение")} onClick={()=>setToast('')}><X size={15}/></button></div>}</div></>}
